import{_ as e,o as i,c as a,ai as n}from"./chunks/framework.C0JxkKN5.js";const g=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"HelpCenter/Shipping&Delivery.md","filePath":"HelpCenter/Shipping&Delivery.md"}'),o={name:"HelpCenter/Shipping&Delivery.md"};function s(r,t,p,c,l,d){return i(),a("div",null,[...t[0]||(t[0]=[n('<h3 id="_1-how-to-select-the-shipping-line-for-products" tabindex="-1">1. How to select the shipping line for products <a class="header-anchor" href="#_1-how-to-select-the-shipping-line-for-products" aria-label="Permalink to “1. How to select the shipping line for products”">​</a></h3><p>On the product detail page, you can select a logistics company. Currently, we support shipping lines provided by <strong>YunExpress</strong>. As the official logistics service provider of TernDrop, YunExpress offers a wide range of shipping options, supporting the transportation of general cargo, products with built-in batteries, cosmetics (liquid &amp; powder).</p><p>Please make sure to choose a logistics route that matches the nature of your product. For example, products with batteries must select a <strong>logistics route</strong> that supports battery transportation. Otherwise, your order cannot be shipped successfully.</p><p><img src="https://media-rs.oss-cn-hongkong.aliyuncs.com/obsidian/2026/05/11/1773404047190-e0b45e8f-f32c-4af0-bded-4ad2f7fc2bbc.png" alt="1773404047190 e0b45e8f f32c 4af0 bded 4ad2f7fc2bbc"></p><h3 id="_2-international-shipping-information-tracking" tabindex="-1">2. International shipping information tracking <a class="header-anchor" href="#_2-international-shipping-information-tracking" aria-label="Permalink to “2. International shipping information tracking”">​</a></h3><p>Click &quot;Order Details&quot; and click the &quot;Fulfillment Log&quot; in the order detail pade. You will be able to see the tracking information there.</p><p><img src="https://media-rs.oss-cn-hongkong.aliyuncs.com/obsidian/2026/05/11/1773404675821-55ba058f-fd06-4cfa-b09e-92f3fb6527c3.png" alt="1773404675821 55ba058f fd06 4cfa b09e 92f3fb6527c3"></p><p><img src="https://media-rs.oss-cn-hongkong.aliyuncs.com/obsidian/2026/05/11/1773404727817-9cd4a20a-1d5f-4afa-8185-d698e8166625.png" alt="1773404727817 9cd4a20a 1d5f 4afa 8185 d698e8166625"></p><h3 id="_3-international-shipping-estimating" tabindex="-1">3. International Shipping Estimating <a class="header-anchor" href="#_3-international-shipping-estimating" aria-label="Permalink to “3. International Shipping Estimating”">​</a></h3><p>On the product detail page, in the <strong>International Shipping Estimate</strong> module, you can enter the product weight and dimensions, then select the logistics company and logistics route. The international shipping cost will be calculated automatically for you.</p><p><img src="https://media-rs.oss-cn-hongkong.aliyuncs.com/obsidian/2026/05/11/1773404960408-9237b8ca-af38-4698-a683-7cb3313640d6.png" alt="1773404960408 9237b8ca af38 4698 a683 7cb3313640d6"></p>',11)])])}const f=e(o,[["render",s]]);export{g as __pageData,f as default};
